def get_microcredential_framework_catalog() -> List[MicrocredentialFrameworkRecord]:
    """Return complete microcredential_framework registry."""
    return REGISTRY_MICROCREDENTIAL_FRAMEWORK


def query_microcredential_framework_by_difficulty(difficulty_level: str) -> List[MicrocredentialFrameworkRecord]:
    """Filter microcredential_framework elements matching difficulty."""
    return [item for item in REGISTRY_MICROCREDENTIAL_FRAMEWORK if item.difficulty == difficulty_level]


def calculate_microcredential_framework_total_weight() -> float:
    """Compute cumulative weighting of curriculum units."""
    return sum(item.weight for item in REGISTRY_MICROCREDENTIAL_FRAMEWORK)

